/* SH-2 instruction semantics for the statically translated program.
 *
 * Converted once from MAME 0.264 src/devices/cpu/sh/sh.cpp
 * (sh_common_execution; license BSD-3-Clause, copyright-holders David Haywood;
 * see LICENSES/) with a mechanical rewrite: m_sh2_state-> to s->, the memory
 * accessors to the sh2_rd and sh2_wr functions, icount to cycles.  Branches and
 * SLEEP are generated by tools/recompilesh2.py; the SH7604-specific LDC SR,
 * RTE, TRAPA and illegal-instruction handling live in runtime/src/sh2_runtime.c. */
#include "sh2/sh2.h"

static inline uint32_t sext32(uint32_t v, int bits) { return (uint32_t)((int32_t)(v << (32 - bits)) >> (32 - bits)); }
#define BITV(x, n) ((((uint32_t)(x)) >> (n)) & 1u)

void sh2_ADD(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] += s->r[m];
}

/*  code                 cycles  t-bit
 *  0111 nnnn iiii iiii  1       -
 *  ADD     #imm,Rn
 */
void sh2_ADDI(sh2_state *s, uint32_t i, uint32_t n)
{
	s->r[n] += sext32(i, 8);
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 1110  1       carry
 *  ADDC    Rm,Rn
 */
void sh2_ADDC(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t tmp0, tmp1;

	tmp1 = s->r[n] + s->r[m];
	tmp0 = s->r[n];
	s->r[n] = tmp1 + (s->sr & SH_T);
	if (tmp0 > tmp1)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
	if (tmp1 > s->r[n])
		s->sr |= SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 1111  1       overflow
 *  ADDV    Rm,Rn
 */
void sh2_ADDV(sh2_state *s, uint32_t m, uint32_t n)
{
	int32_t dest = BITV(s->r[n], 31);
	int32_t src = BITV(s->r[m], 31);
	src += dest;

	s->r[n] += s->r[m];

	int32_t ans = BITV(s->r[n], 31);
	ans += dest;

	if (src != 1)
	{
		if (ans == 1)
			s->sr |= SH_T;
		else
			s->sr &= ~SH_T;
	}
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0010 nnnn mmmm 1001  1       -
 *  AND     Rm,Rn
 */
void sh2_AND(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] &= s->r[m];
}

/*  code                 cycles  t-bit
 *  1100 1001 iiii iiii  1       -
 *  AND     #imm,R0
 */
void sh2_ANDI(sh2_state *s, uint32_t i)
{
	s->r[0] &= i;
}

/*  code                 cycles  t-bit
 *  1100 1101 iiii iiii  1       -
 *  AND.B   #imm,@(R0,GBR)
 */
void sh2_ANDM(sh2_state *s, uint32_t i)
{
	s->ea = s->gbr + s->r[0];
	uint32_t temp = i & sh2_rd8(s->ea);
	sh2_wr8(s->ea, temp);
	s->cycles += 2;
}

/*  code                 cycles  t-bit
 *  1000 1011 dddd dddd  3/1     -
 *  BF      disp8
 */

/*  code                 cycles  t-bit
 *  1000 1111 dddd dddd  3/1     -
 *  BFS     disp8
 */

/*  code                 cycles  t-bit
 *  1010 dddd dddd dddd  2       -
 *  BRA     disp12
 */

/*  code                 cycles  t-bit
 *  0000 mmmm 0010 0011  2       -
 *  BRAF    Rm
 */

/*  code                 cycles  t-bit
 *  1011 dddd dddd dddd  2       -
 *  BSR     disp12
 */

/*  code                 cycles  t-bit
 *  0000 mmmm 0000 0011  2       -
 *  BSRF    Rm
 */

/*  code                 cycles  t-bit
 *  1000 1001 dddd dddd  3/1     -
 *  BT      disp8
 */

/*  code                 cycles  t-bit
 *  1000 1101 dddd dddd  2/1     -
 *  BTS     disp8
 */

/*  code                 cycles  t-bit
 *  0000 0000 0010 1000  1       -
 *  CLRMAC
 */
void sh2_CLRMAC(sh2_state *s)
{
	s->mach = 0;
	s->macl = 0;
}

/*  code                 cycles  t-bit
 *  0000 0000 0000 1000  1       -
 *  CLRT
 */
void sh2_CLRT(sh2_state *s)
{
	s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0000  1       comparison result
 *  CMP_EQ  Rm,Rn
 */
void sh2_CMPEQ(sh2_state *s, uint32_t m, uint32_t n)
{
	if (s->r[n] == s->r[m])
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0011  1       comparison result
 *  CMP_GE  Rm,Rn
 */
void sh2_CMPGE(sh2_state *s, uint32_t m, uint32_t n)
{
	if ((int32_t)s->r[n] >= (int32_t)s->r[m])
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0111  1       comparison result
 *  CMP_GT  Rm,Rn
 */
void sh2_CMPGT(sh2_state *s, uint32_t m, uint32_t n)
{
	if ((int32_t)s->r[n] > (int32_t)s->r[m])
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0110  1       comparison result
 *  CMP_HI  Rm,Rn
 */
void sh2_CMPHI(sh2_state *s, uint32_t m, uint32_t n)
{
	if (s->r[n] > s->r[m])
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0010  1       comparison result
 *  CMP_HS  Rm,Rn
 */
void sh2_CMPHS(sh2_state *s, uint32_t m, uint32_t n)
{
	if (s->r[n] >= s->r[m])
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0100 nnnn 0001 0101  1       comparison result
 *  CMP_PL  Rn
 */
void sh2_CMPPL(sh2_state *s, uint32_t n)
{
	if ((int32_t)s->r[n] > 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0100 nnnn 0001 0001  1       comparison result
 *  CMP_PZ  Rn
 */
void sh2_CMPPZ(sh2_state *s, uint32_t n)
{
	if ((int32_t)s->r[n] >= 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0010 nnnn mmmm 1100  1       comparison result
 * CMP_STR  Rm,Rn
 */
void sh2_CMPSTR(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t temp = s->r[n] ^ s->r[m];
	uint8_t upper_byte = (temp >> 24) & 0xff;
	uint8_t mid_upper_byte = (temp >> 16) & 0xff;
	uint8_t mid_lower_byte = (temp >> 8) & 0xff;
	uint8_t lower_byte = temp & 0xff;
	if (upper_byte && mid_upper_byte && mid_lower_byte && lower_byte)
		s->sr &= ~SH_T;
	else
		s->sr |= SH_T;
}

/*  code                 cycles  t-bit
 *  1000 1000 iiii iiii  1       comparison result
 *  CMP/EQ #imm,R0
 */
void sh2_CMPIM(sh2_state *s, uint32_t i)
{
	uint32_t imm = (uint32_t)sext32(i, 8);

	if (s->r[0] == imm)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0010 nnnn mmmm 0111  1       calculation result
 *  DIV0S   Rm,Rn
 */
void sh2_DIV0S(sh2_state *s, uint32_t m, uint32_t n)
{
	if (!BITV(s->r[n], 31))
		s->sr &= ~SH_Q;
	else
		s->sr |= SH_Q;

	if (!BITV(s->r[m], 31))
		s->sr &= ~SH_M;
	else
		s->sr |= SH_M;

	if (BITV(s->r[m] ^ s->r[n], 31))
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  code                 cycles  t-bit
 *  0000 0000 0001 1001  1       0
 *  DIV0U
 */
void sh2_DIV0U(sh2_state *s)
{
	s->sr &= ~(SH_M | SH_Q | SH_T);
}

/*  code                 cycles  t-bit
 *  0011 nnnn mmmm 0100  1       calculation result
 *  DIV1 Rm,Rn
 */
void sh2_DIV1(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t old_q = s->sr & SH_Q;
	if (0x80000000 & s->r[n])
		s->sr |= SH_Q;
	else
		s->sr &= ~SH_Q;

	s->r[n] = (s->r[n] << 1) | (s->sr & SH_T);

	if (!old_q)
	{
		if (!(s->sr & SH_M))
		{
			uint32_t tmp = s->r[n];
			s->r[n] -= s->r[m];
			if (!(s->sr & SH_Q))
				if (s->r[n] > tmp)
					s->sr |= SH_Q;
				else
					s->sr &= ~SH_Q;
			else
				if (s->r[n] > tmp)
					s->sr &= ~SH_Q;
				else
					s->sr |= SH_Q;
		}
		else
		{
			uint32_t tmp = s->r[n];
			s->r[n] += s->r[m];
			if (!(s->sr & SH_Q))
			{
				if (s->r[n] < tmp)
					s->sr &= ~SH_Q;
				else
					s->sr |= SH_Q;
			}
			else
			{
				if (s->r[n] < tmp)
					s->sr |= SH_Q;
				else
					s->sr &= ~SH_Q;
			}
		}
	}
	else
	{
		if (!(s->sr & SH_M))
		{
			uint32_t tmp = s->r[n];
			s->r[n] += s->r[m];
			if (!(s->sr & SH_Q))
				if (s->r[n] < tmp)
					s->sr |= SH_Q;
				else
					s->sr &= ~SH_Q;
			else
				if (s->r[n] < tmp)
					s->sr &= ~SH_Q;
				else
					s->sr |= SH_Q;
		}
		else
		{
			uint32_t tmp = s->r[n];
			s->r[n] -= s->r[m];
			if (!(s->sr & SH_Q))
				if (s->r[n] > tmp)
					s->sr &= ~SH_Q;
				else
					s->sr |= SH_Q;
			else
				if (s->r[n] > tmp)
					s->sr |= SH_Q;
				else
					s->sr &= ~SH_Q;
		}
	}

	uint32_t tmp = (s->sr & (SH_Q | SH_M));
	if (tmp == 0 || tmp == 0x300) /* if Q == M set T else clear T */
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  DMULS.L Rm,Rn */
void sh2_DMULS(sh2_state *s, uint32_t m, uint32_t n)
{
	int32_t tempn = (int32_t)s->r[n];
	int32_t tempm = (int32_t)s->r[m];
	int fnlml = BITV(tempn ^ tempm, 31);

	if (tempn < 0)
		tempn = 0 - tempn;
	if (tempm < 0)
		tempm = 0 - tempm;

	uint32_t rn_l = (uint32_t)tempn & 0x0000ffff;
	uint32_t rn_h = (uint32_t)tempn >> 16;
	uint32_t rm_l = (uint32_t)tempm & 0x0000ffff;
	uint32_t rm_h = (uint32_t)tempm >> 16;

	uint32_t temp0 = rm_l * rn_l;
	uint32_t temp1 = rm_h * rn_l;
	uint32_t temp2 = rm_l * rn_h;
	uint32_t temp3 = rm_h * rn_h;

	uint32_t res2 = 0;
	uint32_t res1 = temp1 + temp2;
	if (res1 < temp1)
		res2 += 0x00010000;
	temp1 = res1 << 16;

	uint32_t res0 = temp0 + temp1;
	if (res0 < temp0)
		res2++;
	res2 = res2 + (res1 >> 16) + temp3;

	if (fnlml)
	{
		res2 = ~res2;
		if (res0 == 0)
			res2++;
		else
			res0 = (~res0) + 1;
	}

	s->mach = res2;
	s->macl = res0;
	s->cycles++;
}

/*  DMULU.L Rm,Rn */
void sh2_DMULU(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t rn_l = s->r[n] & 0x0000ffff;
	uint32_t rn_h = s->r[n] >> 16;
	uint32_t rm_l = s->r[m] & 0x0000ffff;
	uint32_t rm_h = s->r[m] >> 16;

	uint32_t temp0 = rm_l * rn_l;
	uint32_t temp1 = rm_h * rn_l;
	uint32_t temp2 = rm_l * rn_h;
	uint32_t temp3 = rm_h * rn_h;

	uint32_t res2 = 0;
	uint32_t res1 = temp1 + temp2;
	if (res1 < temp1)
		res2 += 0x00010000;

	temp1 = res1 << 16;
	uint32_t res0 = temp0 + temp1;
	if (res0 < temp0)
		res2++;

	res2 = res2 + (res1 >> 16) + temp3;

	s->mach = res2;
	s->macl = res0;
	s->cycles++;
}

/*  DT      Rn */
void sh2_DT(sh2_state *s, uint32_t n)
{
	s->r[n]--;
	if (s->r[n] == 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  EXTS.B  Rm,Rn */
void sh2_EXTSB(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = sext32(s->r[m], 8);
}

/*  EXTS.W  Rm,Rn */
void sh2_EXTSW(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = sext32(s->r[m], 16);
}

/*  EXTU.B  Rm,Rn */
void sh2_EXTUB(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = s->r[m] & 0x000000ff;
}

/*  EXTU.W  Rm,Rn */
void sh2_EXTUW(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = s->r[m] & 0x0000ffff;
}

