/*  LDC     Rm,GBR */
void sh2_LDCGBR(sh2_state *s, uint32_t m)
{
	s->gbr = s->r[m];
}

/*  LDC     Rm,VBR */
void sh2_LDCVBR(sh2_state *s, uint32_t m)
{
	s->vbr = s->r[m];
}

/*  LDC.L   @Rm+,GBR */
void sh2_LDCMGBR(sh2_state *s, uint32_t m)
{
	s->ea = s->r[m];
	s->gbr = sh2_rd32(s->ea);
	s->r[m] += 4;
	s->cycles += 2;
}

/*  LDC.L   @Rm+,VBR */
void sh2_LDCMVBR(sh2_state *s, uint32_t m)
{
	s->ea = s->r[m];
	s->vbr = sh2_rd32(s->ea);
	s->r[m] += 4;
	s->cycles += 2;
}

/*  LDS     Rm,MACH */
void sh2_LDSMACH(sh2_state *s, uint32_t m)
{
	s->mach = s->r[m];
}

/*  LDS     Rm,MACL */
void sh2_LDSMACL(sh2_state *s, uint32_t m)
{
	s->macl = s->r[m];
}

/*  LDS     Rm,PR */
void sh2_LDSPR(sh2_state *s, uint32_t m)
{
	s->pr = s->r[m];
}

/*  LDS.L   @Rm+,MACH */
void sh2_LDSMMACH(sh2_state *s, uint32_t m)
{
	s->ea = s->r[m];
	s->mach = sh2_rd32(s->ea);
	s->r[m] += 4;
}

/*  LDS.L   @Rm+,MACL */
void sh2_LDSMMACL(sh2_state *s, uint32_t m)
{
	s->ea = s->r[m];
	s->macl = sh2_rd32(s->ea);
	s->r[m] += 4;
}

/*  LDS.L   @Rm+,PR */
void sh2_LDSMPR(sh2_state *s, uint32_t m)
{
	s->ea = s->r[m];
	s->pr = sh2_rd32(s->ea);
	s->r[m] += 4;
}

/*  MAC.L   @Rm+,@Rn+ */
void sh2_MAC_L(sh2_state *s, uint32_t m, uint32_t n)
{
	int32_t tempn = (int32_t)sh2_rd32(s->r[n]);
	s->r[n] += 4;

	int32_t tempm = (int32_t)sh2_rd32(s->r[m]);
	s->r[m] += 4;

	int fnlml = BITV(tempn ^ tempm, 31);

	if (tempn < 0)
		tempn = 0 - tempn;
	if (tempm < 0)
		tempm = 0 - tempm;

	uint32_t rn_l = (uint32_t)tempn & 0x0000ffff;
	uint32_t rn_h = (uint32_t)tempn >> 16;
	uint32_t rm_l = (uint32_t)tempm & 0x0000ffff;
	uint32_t rm_h = (uint32_t)tempm >> 16;

	uint32_t temp0 = rm_l * rn_l;
	uint32_t temp1 = rm_h * rn_l;
	uint32_t temp2 = rm_l * rn_h;
	uint32_t temp3 = rm_h * rn_h;

	uint32_t res2 = 0;
	uint32_t res1 = temp1 + temp2;
	if (res1 < temp1)
		res2 += 0x00010000;
	temp1 = res1 << 16;

	uint32_t res0 = temp0 + temp1;
	if (res0 < temp0)
		res2++;
	res2 = res2 + (res1 >> 16) + temp3;

	if (fnlml)
	{
		res2 = ~res2;
		if (res0 == 0)
			res2++;
		else
			res0 = (~res0) + 1;
	}

	if (s->sr & SH_S)
	{
		res0 = s->macl + res0;
		if (s->macl > res0)
			res2++;
		res2 += s->mach & 0x0000ffff;
		if ((int32_t)res2 < 0 && res2 < 0xffff8000)
		{
			res2 = 0x00008000;
			res0 = 0x00000000;
		}
		else if ((int32_t)res2 > 0 && res2 > 0x00007fff)
		{
			res2 = 0x00007fff;
			res0 = 0xffffffff;
		}
		s->mach = res2;
		s->macl = res0;
	}
	else
	{
		res0 = s->macl + res0;
		if (s->macl > res0)
			res2++;
		res2 += s->mach;
		s->mach = res2;
		s->macl = res0;
	}
	s->cycles += 2;
}

/*  MAC.W   @Rm+,@Rn+ */
void sh2_MAC_W(sh2_state *s, uint32_t m, uint32_t n)
{
	int32_t tempn = (int32_t)(int16_t)sh2_rd16(s->r[n]);
	s->r[n] += 2;

	int32_t tempm = (int32_t)(int16_t)sh2_rd16(s->r[m]);
	s->r[m] += 2;

	uint32_t templ = s->macl;
	tempm *= tempn;

	int32_t dest = BITV(s->macl, 31);
	int32_t src = BITV(tempm, 31) + dest;
	tempn = BITV(tempm, 31) ? -1 : 0;

	s->macl += tempm;

	int32_t ans = BITV(s->macl, 31) + dest;

	if (s->sr & SH_S)
	{
		if (ans == 1)
		{
			if (src == 0)
				s->macl = 0x7fffffff;
			else if (src == 2)
				s->macl = 0x80000000;
		}
	}
	else
	{
		s->mach += tempn;
		if (templ > s->macl)
			s->mach += 1;
	}
	s->cycles += 2;
}

/*  MOV     Rm,Rn */
void sh2_MOV(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = s->r[m];
}

/*  MOV.B   Rm,@Rn */
void sh2_MOVBS(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n];
	sh2_wr8(s->ea, s->r[m] & 0x000000ff);
}

/*  MOV.W   Rm,@Rn */
void sh2_MOVWS(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n];
	sh2_wr16(s->ea, s->r[m] & 0x0000ffff);
}

/*  MOV.L   Rm,@Rn */
void sh2_MOVLS(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->r[m]);
}

/*  MOV.B   @Rm,Rn */
void sh2_MOVBL(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m];
	s->r[n] = (uint32_t)sext32(sh2_rd8(s->ea), 8);
}

/*  MOV.W   @Rm,Rn */
void sh2_MOVWL(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m];
	s->r[n] = (uint32_t)sext32(sh2_rd16(s->ea), 16);
}

/*  MOV.L   @Rm,Rn */
void sh2_MOVLL(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m];
	s->r[n] = sh2_rd32(s->ea);
}

/*  MOV.B   Rm,@-Rn */
void sh2_MOVBM(sh2_state *s, uint32_t m, uint32_t n)
{
	uint8_t data = (uint8_t)s->r[m];

	s->r[n] -= 1;
	sh2_wr8(s->r[n], data);
}

/*  MOV.W   Rm,@-Rn */
void sh2_MOVWM(sh2_state *s, uint32_t m, uint32_t n)
{
	uint16_t data = (uint16_t)s->r[m];

	s->r[n] -= 2;
	sh2_wr16(s->r[n], data);
}

/*  MOV.L   Rm,@-Rn */
void sh2_MOVLM(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t data = s->r[m];

	s->r[n] -= 4;
	sh2_wr32(s->r[n], data);
}

/*  MOV.B   @Rm+,Rn */
void sh2_MOVBP(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = (uint32_t)sext32(sh2_rd8(s->r[m]), 8);
	if (n != m)
		s->r[m] += 1;
}

/*  MOV.W   @Rm+,Rn */
void sh2_MOVWP(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = (uint32_t)sext32(sh2_rd16(s->r[m]), 16);
	if (n != m)
		s->r[m] += 2;
}

/*  MOV.L   @Rm+,Rn */
void sh2_MOVLP(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = sh2_rd32(s->r[m]);
	if (n != m)
		s->r[m] += 4;
}

/*  MOV.B   Rm,@(R0,Rn) */
void sh2_MOVBS0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n] + s->r[0];
	sh2_wr8(s->ea, (uint8_t)s->r[m]);
}

/*  MOV.W   Rm,@(R0,Rn) */
void sh2_MOVWS0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n] + s->r[0];
	sh2_wr16(s->ea, (uint16_t)s->r[m]);
}

/*  MOV.L   Rm,@(R0,Rn) */
void sh2_MOVLS0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[n] + s->r[0];
	sh2_wr32(s->ea, s->r[m]);
}

/*  MOV.B   @(R0,Rm),Rn */
void sh2_MOVBL0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m] + s->r[0];
	s->r[n] = (uint32_t)sext32(sh2_rd8(s->ea), 8);
}

/*  MOV.W   @(R0,Rm),Rn */
void sh2_MOVWL0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m] + s->r[0];
	s->r[n] = (uint32_t)sext32(sh2_rd16(s->ea), 16);
}

/*  MOV.L   @(R0,Rm),Rn */
void sh2_MOVLL0(sh2_state *s, uint32_t m, uint32_t n)
{
	s->ea = s->r[m] + s->r[0];
	s->r[n] = sh2_rd32(s->ea);
}

/*  MOV     #imm,Rn */
void sh2_MOVI(sh2_state *s, uint32_t i, uint32_t n)
{
	s->r[n] = (uint32_t)sext32(i, 8);
}

/*  MOV.W   @(disp8,PC),Rn */
void sh2_MOVWI(sh2_state *s, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0xff;
	s->ea = s->pc + disp * 2 + 2;
	s->r[n] = (uint32_t)sext32(sh2_rd16(s->ea), 16);
}

/*  MOV.L   @(disp8,PC),Rn */
void sh2_MOVLI(sh2_state *s, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0xff;
	s->ea = ((s->pc + 2) & ~3) + disp * 4;
	s->r[n] = sh2_rd32(s->ea);
}

/*  MOV.B   @(disp8,GBR),R0 */
void sh2_MOVBLG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp;
	s->r[0] = (uint32_t)sext32(sh2_rd8(s->ea), 8);
}

/*  MOV.W   @(disp8,GBR),R0 */
void sh2_MOVWLG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp * 2;
	s->r[0] = (int32_t)sext32(sh2_rd16(s->ea), 16);
}

/*  MOV.L   @(disp8,GBR),R0 */
void sh2_MOVLLG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp * 4;
	s->r[0] = sh2_rd32(s->ea);
}

/*  MOV.B   R0,@(disp8,GBR) */
void sh2_MOVBSG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp;
	sh2_wr8(s->ea, (uint8_t)s->r[0]);
}

/*  MOV.W   R0,@(disp8,GBR) */
void sh2_MOVWSG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp * 2;
	sh2_wr16(s->ea, (uint16_t)s->r[0]);
}

/*  MOV.L   R0,@(disp8,GBR) */
void sh2_MOVLSG(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = s->gbr + disp * 4;
	sh2_wr32(s->ea, s->r[0]);
}

/*  MOV.B   R0,@(disp4,Rn) */
void sh2_MOVBS4(sh2_state *s, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[n] + disp;
	sh2_wr8(s->ea, (uint8_t)s->r[0]);
}

/*  MOV.W   R0,@(disp4,Rn) */
void sh2_MOVWS4(sh2_state *s, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[n] + disp * 2;
	sh2_wr16(s->ea, (uint16_t)s->r[0]);
}

/* MOV.L Rm,@(disp4,Rn) */
void sh2_MOVLS4(sh2_state *s, uint32_t m, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[n] + disp * 4;
	sh2_wr32(s->ea, s->r[m]);
}

/*  MOV.B   @(disp4,Rm),R0 */
void sh2_MOVBL4(sh2_state *s, uint32_t m, uint32_t d)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[m] + disp;
	s->r[0] = (uint32_t)sext32(sh2_rd8(s->ea), 8);
}

/*  MOV.W   @(disp4,Rm),R0 */
void sh2_MOVWL4(sh2_state *s, uint32_t m, uint32_t d)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[m] + disp * 2;
	s->r[0] = (uint32_t)sext32(sh2_rd16(s->ea), 16);
}

/*  MOV.L   @(disp4,Rm),Rn */
void sh2_MOVLL4(sh2_state *s, uint32_t m, uint32_t d, uint32_t n)
{
	uint32_t disp = d & 0x0f;
	s->ea = s->r[m] + disp * 4;
	s->r[n] = sh2_rd32(s->ea);
}

/*  MOVA    @(disp8,PC),R0 */
void sh2_MOVA(sh2_state *s, uint32_t d)
{
	uint32_t disp = d & 0xff;
	s->ea = ((s->pc + 2) & ~3) + disp * 4;
	s->r[0] = s->ea;
}

/*  MOVT    Rn */
void sh2_MOVT(sh2_state *s, uint32_t n)
{
	s->r[n] = s->sr & SH_T;
}

/*  MUL.L   Rm,Rn */
void sh2_MULL(sh2_state *s, uint32_t m, uint32_t n)
{
	s->macl = s->r[n] * s->r[m];
	s->cycles++;
}

/*  MULS    Rm,Rn */
void sh2_MULS(sh2_state *s, uint32_t m, uint32_t n)
{
	s->macl = (int16_t)s->r[n] * (int16_t)s->r[m];
}

/*  MULU    Rm,Rn */
void sh2_MULU(sh2_state *s, uint32_t m, uint32_t n)
{
	s->macl = (uint16_t)s->r[n] * (uint16_t)s->r[m];
}

/*  NEG     Rm,Rn */
void sh2_NEG(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = 0 - s->r[m];
}

/*  NEGC    Rm,Rn */
void sh2_NEGC(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t temp = s->r[m];
	s->r[n] = -temp - (s->sr & SH_T);
	if (temp || (s->sr & SH_T))
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  NOP */
void sh2_NOP(sh2_state *s)
{
}

/*  NOT     Rm,Rn */
void sh2_NOT(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = ~s->r[m];
}

/*  OR      Rm,Rn */
void sh2_OR(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] |= s->r[m];
}

/*  OR      #imm,R0 */
void sh2_ORI(sh2_state *s, uint32_t i)
{
	s->r[0] |= i;
	s->cycles += 2;
}

/*  OR.B    #imm,@(R0,GBR) */
void sh2_ORM(sh2_state *s, uint32_t i)
{
	s->ea = s->gbr + s->r[0];
	sh2_wr8(s->ea, sh2_rd8(s->ea) | (uint8_t)i);
}

/*  ROTCL   Rn */
void sh2_ROTCL(sh2_state *s, uint32_t n)
{
	uint32_t temp = (s->r[n] >> 31) & SH_T;
	s->r[n] = (s->r[n] << 1) | (s->sr & SH_T);
	s->sr = (s->sr & ~SH_T) | temp;
}

/*  ROTCR   Rn */
void sh2_ROTCR(sh2_state *s, uint32_t n)
{
	uint32_t temp = (s->sr & SH_T) << 31;
	if (s->r[n] & SH_T)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
	s->r[n] = (s->r[n] >> 1) | temp;
}

/*  ROTL    Rn */
void sh2_ROTL(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | ((s->r[n] >> 31) & SH_T);
	s->r[n] = ((s->r[n] << 1) | (s->r[n] >> 31));
}

/*  ROTR    Rn */
void sh2_ROTR(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | (s->r[n] & SH_T);
	s->r[n] = ((s->r[n] >> 1) | (s->r[n] << 31));
}

/*  RTS */

/*  SETT */
void sh2_SETT(sh2_state *s)
{
	s->sr |= SH_T;
}

/*  SHAL    Rn      (same as SHLL) */
void sh2_SHAL(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | ((s->r[n] >> 31) & SH_T);
	s->r[n] <<= 1;
}

/*  SHAR    Rn */
void sh2_SHAR(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | (s->r[n] & SH_T);
	s->r[n] = (uint32_t)((int32_t)s->r[n] >> 1);
}

/*  SHLL    Rn      (same as SHAL) */
void sh2_SHLL(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | ((s->r[n] >> 31) & SH_T);
	s->r[n] <<= 1;
}

/*  SHLL2   Rn */
void sh2_SHLL2(sh2_state *s, uint32_t n)
{
	s->r[n] <<= 2;
}

/*  SHLL8   Rn */
void sh2_SHLL8(sh2_state *s, uint32_t n)
{
	s->r[n] <<= 8;
}

/*  SHLL16  Rn */
void sh2_SHLL16(sh2_state *s, uint32_t n)
{
	s->r[n] <<= 16;
}

/*  SHLR    Rn */
void sh2_SHLR(sh2_state *s, uint32_t n)
{
	s->sr = (s->sr & ~SH_T) | (s->r[n] & SH_T);
	s->r[n] >>= 1;
}

/*  SHLR2   Rn */
void sh2_SHLR2(sh2_state *s, uint32_t n)
{
	s->r[n] >>= 2;
}

/*  SHLR8   Rn */
void sh2_SHLR8(sh2_state *s, uint32_t n)
{
	s->r[n] >>= 8;
}

/*  SHLR16  Rn */
void sh2_SHLR16(sh2_state *s, uint32_t n)
{
	s->r[n] >>= 16;
}


/*  STC     SR,Rn */
void sh2_STCSR(sh2_state *s, uint32_t n)
{
	s->r[n] = s->sr;
}

/*  STC     GBR,Rn */
void sh2_STCGBR(sh2_state *s, uint32_t n)
{
	s->r[n] = s->gbr;
}

/*  STC     VBR,Rn */
void sh2_STCVBR(sh2_state *s, uint32_t n)
{
	s->r[n] = s->vbr;
}

/*  STC.L   SR,@-Rn */
void sh2_STCMSR(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->sr);
	s->cycles++;
}

/*  STC.L   GBR,@-Rn */
void sh2_STCMGBR(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->gbr);
	s->cycles++;
}

/*  STC.L   VBR,@-Rn */
void sh2_STCMVBR(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->vbr);
	s->cycles++;
}

/*  STS     MACH,Rn */
void sh2_STSMACH(sh2_state *s, uint32_t n)
{
	s->r[n] = s->mach;
}

/*  STS     MACL,Rn */
void sh2_STSMACL(sh2_state *s, uint32_t n)
{
	s->r[n] = s->macl;
}

/*  STS     PR,Rn */
void sh2_STSPR(sh2_state *s, uint32_t n)
{
	s->r[n] = s->pr;
}

/*  STS.L   MACH,@-Rn */
void sh2_STSMMACH(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->mach);
}

/*  STS.L   MACL,@-Rn */
void sh2_STSMMACL(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->macl);
}

/*  STS.L   PR,@-Rn */
void sh2_STSMPR(sh2_state *s, uint32_t n)
{
	s->r[n] -= 4;
	s->ea = s->r[n];
	sh2_wr32(s->ea, s->pr);
}

/*  SUB     Rm,Rn */
void sh2_SUB(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] -= s->r[m];
}

/*  SUBC    Rm,Rn */
void sh2_SUBC(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t tmp1 = s->r[n] - s->r[m];
	uint32_t tmp0 = s->r[n];
	s->r[n] = tmp1 - (s->sr & SH_T);
	if (tmp0 < tmp1)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
	if (tmp1 < s->r[n])
		s->sr |= SH_T;
}

/*  SUBV    Rm,Rn */
void sh2_SUBV(sh2_state *s, uint32_t m, uint32_t n)
{
	int32_t dest = BITV(s->r[n], 31);
	int32_t src = BITV(s->r[m], 31);
	src += dest;

	s->r[n] -= s->r[m];

	int32_t ans = BITV(s->r[n], 31);
	ans += dest;

	if (src == 1 && ans == 1)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  SWAP.B  Rm,Rn */
void sh2_SWAPB(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t temp = s->r[m] & 0xffff0000;
	temp |= (s->r[m] & 0x000000ff) << 8;
	s->r[n] = (uint8_t)(s->r[m] >> 8);
	s->r[n] = s->r[n] | temp;
}

/*  SWAP.W  Rm,Rn */
void sh2_SWAPW(sh2_state *s, uint32_t m, uint32_t n)
{
	uint32_t temp = s->r[m] >> 16;
	s->r[n] = (s->r[m] << 16) | temp;
}

/*  TAS.B   @Rn */
void sh2_TAS(sh2_state *s, uint32_t n)
{
	s->ea = s->r[n];

	/* Bus Lock enable */
	uint32_t temp = sh2_rd8(s->ea);
	if (temp == 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
	temp |= 0x80;
	/* Bus Lock disable */
	sh2_wr8(s->ea, temp);
	s->cycles += 3;
}

/*  TST     Rm,Rn */
void sh2_TST(sh2_state *s, uint32_t m, uint32_t n)
{
	if ((s->r[n] & s->r[m]) == 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  TST     #imm,R0 */
void sh2_TSTI(sh2_state *s, uint32_t i)
{
	uint32_t imm = i & 0xff;

	if ((imm & s->r[0]) == 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
}

/*  TST.B   #imm,@(R0,GBR) */
void sh2_TSTM(sh2_state *s, uint32_t i)
{
	uint32_t imm = i & 0xff;

	s->ea = s->gbr + s->r[0];
	if ((imm & sh2_rd8(s->ea)) == 0)
		s->sr |= SH_T;
	else
		s->sr &= ~SH_T;
	s->cycles += 2;
}

/*  XOR     Rm,Rn */
void sh2_XOR(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] ^= s->r[m];
}

/*  XOR     #imm,R0 */
void sh2_XORI(sh2_state *s, uint32_t i)
{
	s->r[0] ^= i & 0x000000ff;
}

/*  XOR.B   #imm,@(R0,GBR) */
void sh2_XORM(sh2_state *s, uint32_t i)
{
	s->ea = s->gbr + s->r[0];
	sh2_wr8(s->ea, sh2_rd8(s->ea) ^ (uint8_t)i);
	s->cycles += 2;
}

/*  XTRCT   Rm,Rn */
void sh2_XTRCT(sh2_state *s, uint32_t m, uint32_t n)
{
	s->r[n] = (s->r[n] >> 16) | (s->r[m] << 16);
}

/*  SLEEP */

